def compact_specials(grid):
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    # Extract special pixels sorted by position
    specials = []
    for r in range(height):
        for c in range(width):
            if grid[r][c] != 2:
                specials.append((r, c, grid[r][c]))

    # Create new grid
    result = [[2 for _ in range(width)] for _ in range(height)]

    # Fill starting from top-left in reading order
    idx = 0
    for r in range(height):
        for c in range(width):
            if idx < len(specials):
                result[r][c] = specials[idx][2]
                idx += 1

    return result

